create or replace function academy_tracker.learning_insights()
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare u uuid:=academy_tracker.require_access(); out jsonb;
begin
with objective as (select 'tef-reading'::text as module, test_id as test, submitted_at as at, case when jsonb_typeof(result->'points')='number' and jsonb_typeof(result->'maxPoints')='number' then round(100*(result->>'points')::numeric/nullif((result->>'maxPoints')::numeric,0),1) end as percent, result->>'correct' as correct,result->>'total' as total from academy_tef_reading.attempts where user_id=u and status='completed' and submitted_at is not null union all select 'tef-listening'::text as module, test_id as test, submitted_at as at, case when jsonb_typeof(result->'points')='number' and jsonb_typeof(result->'maxPoints')='number' then round(100*(result->>'points')::numeric/nullif((result->>'maxPoints')::numeric,0),1) end as percent, result->>'correct' as correct,result->>'total' as total from academy_tef_listening.attempts where user_id=u and status='completed' and submitted_at is not null union all select 'tcf-reading'::text as module, test_id as test, submitted_at as at, case when jsonb_typeof(result->'points')='number' and jsonb_typeof(result->'maxPoints')='number' then round(100*(result->>'points')::numeric/nullif((result->>'maxPoints')::numeric,0),1) end as percent, result->>'correct' as correct,result->>'total' as total from academy_tcf_reading.attempts where user_id=u and status='completed' and submitted_at is not null union all select 'tcf-listening'::text as module, test_id as test, submitted_at as at, case when jsonb_typeof(result->'points')='number' and jsonb_typeof(result->'maxPoints')='number' then round(100*(result->>'points')::numeric/nullif((result->>'maxPoints')::numeric,0),1) end as percent, result->>'correct' as correct,result->>'total' as total from academy_tcf_listening.attempts where user_id=u and status='completed' and submitted_at is not null),
reviews as (select case when kind like '%-speaking-feedback' then replace(kind,'-feedback','') else kind end module, updated_at as at, result, level, kind from academy_ai.requests where user_id=u and status='completed' and kind in ('pronunciation','conversation','writing','tef-writing','tcf-writing','tef-speaking-feedback','tcf-speaking-feedback')),
fullreviews as (select * from reviews where module not in ('pronunciation','conversation','writing') and (kind<>'tef-speaking-feedback' or result->>'section'='B')),
events as (select module,at from objective union all select module,at from fullreviews union all select module,at from reviews where module in ('pronunciation','conversation','writing') union all select 'lesson',updated_at from public.academy_learning_progress where user_id=u and completed),
mods as (select unnest(array['tef-reading','tef-listening','tef-writing','tef-speaking','tcf-reading','tcf-listening','tcf-writing','tcf-speaking','pronunciation','conversation','writing']) module),
days as (select d::date as day from generate_series(current_date-29,current_date,interval '1 day') d)
select jsonb_build_object(
'generatedAt',now(),
'course',(select jsonb_build_object('completed',count(*) filter(where coalesce(p.completed,false)),'total',count(*),'levels',coalesce(jsonb_agg(jsonb_build_object('level',a.level,'completed',coalesce(p.completed,false),'best',p.best_percent)) filter(where p.user_id is not null),'[]')) from public.academy_units a left join public.academy_learning_progress p on p.unit_id=a.id and p.user_id=u where a.published),
'skills',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from (select e.skill,count(*) total,count(*) filter(where e.last_correct) correct,count(*) filter(where e.wrong_count>0) mistakes from academy_tracker.evidence e join public.academy_units a on a.id=e.unit_id and a.published where e.user_id=u group by e.skill)s),
'placement',(select jsonb_build_object('level',result->>'recommendedLevel','provisional',result->'provisional') from academy_placement.attempts where user_id=u and status='completed' order by completed_at desc limit 1),
'modules',(select jsonb_agg(jsonb_build_object('module',m.module,'count',(select count(*) from events e where e.module=m.module),'average',(select round(avg(percent),1) from objective o where o.module=m.module),'best',(select max(percent) from objective o where o.module=m.module),'recent',(select coalesce(jsonb_agg(to_jsonb(z) order by z.at),'[]') from (select test,at,percent,correct,total from objective o where o.module=m.module order by at desc limit 10)z),'latestEstimate',(select jsonb_build_object('score',result->'score','nclc',result->'nclc','at',at,'status',result->>'scoreStatus') from fullreviews r where r.module=m.module order by at desc limit 1))) from mods m),
'activity',(select jsonb_agg(jsonb_build_object('day',d.day,'count',(select count(*) from events e where (e.at at time zone 'UTC')::date=d.day)) order by d.day) from days d),
'recentFeedback',(select coalesce(jsonb_agg(to_jsonb(z) order by z.at desc),'[]') from (select module,at,level,left(coalesce(result->>'feedback',result->>'summary',result->>'scoreReason',''),350) summary,(select coalesce(jsonb_agg(left(coalesce(x->>'improvement',x->>'tip',x->>'explanation',''),180)),'[]') from (select value x from jsonb_array_elements(case when jsonb_typeof(coalesce(result->'criteria',result->'focus',result->'corrections'))='array' then coalesce(result->'criteria',result->'focus',result->'corrections') else '[]' end) limit 3) a) tips from reviews where kind<>'tef-speaking-feedback' or result->>'section'='B' order by at desc limit 12)z),
'notebookDue',(select count(*) from academy_tracker.evidence where user_id=u and wrong_count>0 and due_at<=now())
) into out;
return out;
end;$fn$;
revoke all on function academy_tracker.learning_insights() from public,anon;
grant execute on function academy_tracker.learning_insights() to authenticated;
create or replace function public.academy_learning_insights() returns jsonb language sql set search_path='' as $fn$ select academy_tracker.learning_insights() $fn$;
revoke all on function public.academy_learning_insights() from public,anon;
grant execute on function public.academy_learning_insights() to authenticated;